"use strict";
window.ObsBlueprintCards={clean(v){return String(v||'').replace(/\\n/g,'\n').replace(/<[^>]*>/g,'').replace(/^#\s*/gm,'').trim();},
 render(i,single){if(i.category==='Auftrag angenommen')return `<article class="alert-item"><h2>${escapeText(i.name)}</h2><p>${escapeText(i.description)}</p></article>`;const e=escapeText,clean=this.clean(i.description),lines=clean.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),labels=['Hersteller','Typ (En)','Typ (De)','Größe','Gütegrad','Klasse'];
 const facts=labels.map(label=>[label,lines.find(line=>line.toLowerCase().startsWith(label.toLowerCase()+':'))?.slice(label.length+1).trim()|| (label==='Hersteller'?i.manufacturer:'—')]);
 const basic=new Set(labels.map(s=>s.toLowerCase()));const extra=lines.filter(line=>!basic.has(line.split(':')[0].toLowerCase()));const prose=extra.filter(line=>!line.includes(':')&&!/^[-•]/.test(line));const technical=extra.filter(line=>line.includes(':')||/^[-•]/.test(line));
 const images=settings.showImage?(i.images||[]).map(x=>x.original_url||x.thumbnail_url).filter(x=>x?.startsWith('/media/')):[];
 return `<article class="alert-item blueprint-info"><div class="alert-item-visual">${images.length?`<img src="${e(images[0])}" data-image-list="${e(JSON.stringify(images))}" alt="${e(i.name)}"/>`:'<span>Kein Bild verfügbar</span>'}</div><div class="blueprint-info-text"><h2>${e(i.name)}</h2><dl>${facts.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v||'—')}</dd></div>`).join('')}</dl>${single?`<p>${e(prose.join(' '))}</p><h3>Technik und Herstellung</h3><dl class="blueprint-technical">${technical.map(line=>{const at=line.indexOf(':');return `<div><dt>${e(at>=0?line.slice(0,at):'Material')}</dt><dd>${e(at>=0?line.slice(at+1).trim():line)}</dd></div>`;}).join('')}</dl>`:''}</div></article>`;},
 rotate(){clearInterval(this.timer);this.timer=setInterval(()=>{document.querySelectorAll('[data-image-list]').forEach(img=>{const list=JSON.parse(img.dataset.imageList);if(list.length<2)return;img.dataset.imageIndex=String(((Number(img.dataset.imageIndex)||0)+1)%list.length);img.src=list[Number(img.dataset.imageIndex)];});},(settings.imageIntervalSeconds||5)*1000);}
};
